/* One owner for each movement control; rendering never leaves detached duplicates. */
(()=>{'use strict';
const $=id=>document.getElementById(id),T=(a,b)=>document.documentElement.lang.startsWith('zh')?b:a;
const paths={check:'<path d="m4 12 5 5L21 5"/>',pause:'<path d="M8 4v16M16 4v16" stroke-width="4"/>',play:'<path d="m7 3 14 9-14 9z"/>',settings:'<path d="m9 3-1 3-3 1-2 4 2 3 3 1 1 4h6l1-4 3-1 2-3-2-4-3-1-1-3z"/><circle cx="12" cy="11" r="3"/>',language:'<path d="M2 5h12M8 2v3M4 5q0 9 10 12M12 5Q10 14 2 17M14 22l4-11 4 11m-6-4h4"/>',sound:'<path d="M3 9h5l5-5v16l-5-5H3zM17 7q6 5 0 10"/>',close:'<path d="m5 5 14 14M19 5 5 19"/>',back:'<path d="m14 4-8 8 8 8"/>',reset:'<path d="M3 3v7h7M3 10a9 9 0 1 1 1 9"/>',next:'<path d="m14 4 8 8-8 8M2 12h20"/>',hint:'<path d="M8 17c0-3-3-4-3-8a7 7 0 0 1 14 0c0 4-3 5-3 8zM9 21h6"/>'};
function art(kind){return '<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">'+(paths[kind]||paths.close)+'</svg>'}
function decorate(b,kind,label,visible=false){if(!b)return;b.innerHTML=art(kind)+(visible?'<span>'+label+'</span>':'');b.setAttribute('aria-label',label);b.title=label;b.classList.add('movement-icon');b.classList.toggle('labelled-action',visible);b.classList.toggle('movement-hint',kind==='hint');}
let activeDialog=null;
function dialog(title,body,close){if(activeDialog)return;const opener=document.activeElement,d=document.createElement('dialog');d.className='movement-confirm';d.setAttribute('aria-label',title);d.innerHTML='<h2>'+title+'</h2>';d.append(body);document.body.append(d);activeDialog=d;let closed=false;const done=()=>{if(closed)return;closed=true;d.close?.();d.remove();activeDialog=null;close?.();if(opener?.isConnected)opener.focus()};d.addEventListener('cancel',e=>{e.preventDefault();done()});d.showModal?.();if(!d.open)d.setAttribute('open','');d.querySelector('button,select')?.focus();return done;}
function settings(){const api=window.MindGardenMovementActivity,wasPaused=api.paused;api.pause(true);const content=document.createElement('div');content.innerHTML='<label for="movementPace">'+T('Pace','节奏')+'</label><select id="movementPace"><option value="slow">'+T('Slow','慢速')+'</option><option value="regular">'+T('Regular','常规')+'</option><option value="manual">'+T('At my pace','按我的节奏')+'</option></select><div class="movement-settings-actions"></div>';const safety=document.createElement('p');safety.textContent=T('Move within your comfortable range. Stop if you feel pain, dizzy or unwell.','请在舒适范围内活动。如感到疼痛、头晕或不适，请停止。');content.append(safety);content.querySelector('select').value=api.pace;content.querySelector('select').onchange=e=>api.setPace(e.target.value);const actions=content.querySelector('.movement-settings-actions'),done=document.createElement('button');done.textContent=T('Done','完成');done.className='primary';actions.append(done);const close=dialog(T('Settings','设置'),content,()=>api.pause(wasPaused));done.onclick=close;}
function mount(){const header=document.querySelector('header'),footer=$('footer'),api=window.MindGardenMovementActivity;if(!header||!footer)return;
 const phase=document.body.dataset.phase,finished=phase==='finished',setup=phase==='setup';
 decorate($('brand'),'back',T('Back to games','返回游戏'));decorate($('language'),'language',T('Language: English / Chinese','语言：英文 / 中文'));
 const voice=$('voice');if(voice){header.append(voice);decorate(voice,'sound',T('Voice','语音'));voice.classList.toggle('sound-muted',voice.getAttribute('aria-pressed')==='false')}
 const stages=$('stages');if(stages.parentElement!==$('content').parentElement||stages.nextElementSibling!==$('content'))$('content').before(stages);stages.hidden=finished||setup;
 footer.replaceChildren();if(!finished&&!setup){for(const [id,kind,en,zh]of [['pause',api?.paused?'play':'pause',api?.paused?'Resume':'Pause',api?.paused?'继续':'暂停'],['repeat','hint','Hint','提示'],['again','hint','Hint','提示']]){const b=$(id);if(b){decorate(b,kind,T(en,zh),true);footer.append(b)}}const gear=document.createElement('button');gear.id='movementSettings';decorate(gear,'settings',T('Settings','设置'),true);gear.onclick=settings;footer.append(gear)}footer.hidden=finished||setup;
 for(const [id,kind,en,zh]of [['replay','reset','Replay','重玩'],['nextLevel','next','Next level','下一关'],['resultDone','check','Done','完成']])decorate($(id),kind,T(en,zh),true);
 $('subtitle').hidden=!setup;header.hidden=finished;
}
const allowed=new WeakSet();document.addEventListener('click',e=>{const b=e.target.closest('#brand');if(!b||allowed.has(b)){if(b)allowed.delete(b);return}const api=window.MindGardenMovementActivity;if(['setup','finished'].includes(api.phase))return;e.preventDefault();e.stopImmediatePropagation();const paused=api.paused;api.pause(true);const body=document.createElement('div');body.innerHTML='<p>'+T('Your unfinished activity will end.','尚未完成的活动将结束。')+'</p><div class="movement-settings-actions"><button class="primary">'+T('Keep playing','继续游戏')+'</button><button>'+T('Exit','退出')+'</button></div>';let accepted=false;const close=dialog(T('Confirm Exit?','确认退出？'),body,()=>{if(!accepted)api.pause(paused)});const buttons=body.querySelectorAll('button');buttons[0].onclick=close;buttons[1].onclick=()=>{accepted=true;close();allowed.add(b);b.click()};},true);
window.addEventListener('movementRender',mount);mount();
})();
